-- ====================================================================================
-- HEIRLOOM TIER 3 BAG - TIERED SLOT-COUNT ITEMS
-- ====================================================================================
-- Database: acore_world
--
-- The 3.3.5a client reads a container's slot count from its static per-itemID
-- item-info cache (same source as the tooltip's "X Slot Bag" line), not the live
-- per-instance object field, so growing entry 300366's CONTAINER_FIELD_NUM_SLOTS
-- server-side never renders more slots client-side. heirloom_scaling_255.cpp now
-- swaps the equipped bag through these real, separate item_template rows instead
-- (302607-302611) as the owner levels - each is a plain clone of 300366 with only
-- `name` and `ContainerSlots` changed. See src/server/scripts/DC/ItemUpgrades/
-- heirloom_scaling_255.cpp for the tier/level table.
--
-- These are internal swap-only items: intentionally NOT added to
-- dc_heirloom_definitions, so the collection system keeps tracking ownership
-- against the single canonical entry 300366 and never shows 6 separate unlocks.
-- ====================================================================================

DELETE FROM `item_template` WHERE `entry` IN (302607, 302608, 302609, 302610, 302611);
